  cursor: pointer;
}
.ent-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.ent-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ent-card-image.gradient-streaming { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); }
.ent-card-image.gradient-fitness { background: linear-gradient(135deg, #1b5e20 0%, #2e7d32 100%); }
.ent-card-image.gradient-gaming { background: linear-gradient(135deg, #311b92 0%, #4527a0 100%); }
.ent-card-image.gradient-music { background: linear-gradient(135deg, #b71c1c 0%, #d32f2f 100%); }
.ent-card-image svg { width: 60px; height: 60px; opacity: 0.5; color: white; }
.ent-card-body {
  padding: 16px 20px;
  background: var(--color-white);
}
.ent-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}
.ent-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}
.ent-card-body .cta-link {
  font-size: 13px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Store Hero ===== */
.store-hero {
  text-align: center;
  padding: 80px 24px 60px;
  background: var(--color-white);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.07;
  margin-bottom: 8px;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  letter-spacing: -0.15px;
  margin-bottom: 28px;
}
.cta-group {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}
.cta-btn {
  padding: 11px 22px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: inherit;
  letter-spacing: -0.1px;
}
.cta-btn.primary {
  background: var(--color-accent);
  color: white;
  border: none;
}
.cta-btn.primary:hover { background: var(--color-accent-hover); }
.cta-btn.secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}
.cta-btn.secondary:hover { background: rgba(0,102,204,0.05); }

/* ===== Help & Support Cards ===== */
.help-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.help-cards::-webkit-scrollbar { display: none; }
.help-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.help-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.help-card-icon svg { width: 24px; height: 24px; }
.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Store Difference / Savings Cards ===== */
.diff-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.diff-cards::-webkit-scrollbar { display: none; }
.diff-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.diff-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.diff-card-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
}
.diff-card-icon svg { width: 22px; height: 22px; }
.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.diff-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Brand Collab ===== */
.brand-collab {
  text-align: center;
  padding: 80px 24px;
  background: var(--color-white);
  margin: 0 24px;
  border-radius: var(--radius-xl);
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}
.brand-collab h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.brand-collab .logos {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 8px;
}
.brand-collab p {
  font-size: 19px;
  color: var(--color-text-secondary);
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 0 24px;
}
.quick-link {
  padding: 10px 20px;
  background: var(--color-white);
  border-radius: 24px;
  font-size: 14px;
  color: var(--color-text);
  font-weight: 500;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  border: 1px solid var(--color-border);
}
.quick-link:hover {
  box-shadow: var(--shadow-md);
  text-decoration: none;
  color: var(--color-accent);
}

/* ===== Category Hero ===== */
.cat-hero {
  text-align: center;
  padding: 64px 24px 32px;
  background: var(--color-white);
}
.cat-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.cat-hero p {
  font-size: 19px;
  color: var(--color-text-secondary);
}

/* ===== Sticky Section Nav ===== */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  z-index: 99;
  overflow-x: auto;
  scrollbar-width: none;
  display: flex;
  justify-content: center;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
}
.section-nav-link {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: inherit;
  letter-spacing: -0.08px;
}
.section-nav-link:hover { color: var(--color-text); }
.section-nav-link.active { color: var(--color-text); border-bottom-color: var(--color-text); }

/* ===== Guide Cards ===== */
.guide-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.guide-cards::-webkit-scrollbar { display: none; }
.guide-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.guide-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Special Stores ===== */
.special-stores {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.special-stores::-webkit-scrollbar { display: none; }
.special-store-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.special-store-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* ===== Audio Promo ===== */
.audio-promo {
  text-align: center;
  font-size: 15px;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
  padding: 12px 24px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  display: inline-block;
}

/* ===== Category Audio/Accessories ===== */
.cat-product-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.cat-product-cards::-webkit-scrollbar { display: none; }
.cat-product-card {
  flex: 0 0 220px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.cat-product-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.cat-product-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cat-product-card-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.cat-product-card-image svg { width: 70px; height: 70px; opacity: 0.35; }
.cat-product-card-badge-top {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--color-accent);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
}
.cat-product-card-body {
  padding: 14px 16px 18px;
}
.cat-product-card-body h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.cat-product-card-body .note {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}
.cat-product-card-body .price {
  font-size: 14px;
  font-weight: 500;
}

/* ===== Section backgrounds ===== */
.bg-white { background: var(--color-white); }
.bg-alt { background: var(--color-bg-alt); }

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-alt);
  padding: 40px 24px 24px;
  border-top: 1px solid var(--color-border);
}
.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 10px;
  color: var(--color-text);
  letter-spacing: -0.08px;
}
.footer-col ul {
  list-style: none;
}
.footer-col ul li {
  margin-bottom: 6px;
}
.footer-col ul li a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col ul li a:hover {
  color: var(--color-text);
  text-decoration: none;
}
.footer-bottom {
  max-width: var(--max-width);
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}
.footer-bottom p {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 8px;
}

/* ===== Responsive ===== */

/* Tablet */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile-image {
    height: 280px;
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .carousel-card { flex: 0 0 260px; }
  .hero h1, .store-hero h1, .cat-hero h1 {
    font-size: 40px;
  }
  .section { padding: 56px 0; }
}

/* Mobile */
@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(251, 251, 253, 0.98);
    backdrop-filter: blur(20px);
    flex-direction: column;
    padding: 20px 24px;
    gap: 16px;
    border-bottom: 1px solid var(--color-border);
  }
  .nav-links.open { display: flex; }
  .nav-mobile-toggle { display: block; }

  .hero h1 { font-size: 36px; }
  .hero .hero-sub { font-size: 17px; }
  .store-hero h1 { font-size: 40px; }
  .store-hero .subtitle { font-size: 18px; }
  .cat-hero h1 { font-size: 36px; }

  .section-header h2 { font-size: 32px; }
  .section-header p { font-size: 16px; }
  .section { padding: 48px 0; }

  .product-tile-image { height: 240px; }
  .product-tile-body h3 { font-size: 24px; }
  .product-tile-body p { font-size: 15px; }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  /* Footer accordion on mobile */
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px solid var(--color-border);
    margin-bottom: 0;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 400;
    transition: transform 0.3s;
  }
  .footer-col h4.open::after {
    content: '\2212';
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
  }
  .footer-col ul.open {
    max-height: 600px;
    padding: 10px 0;
  }

  .carousel-card { flex: 0 0 240px; }
  .carousel-btn { display: none; }

  .brand-collab h2 { font-size: 32px; }
  .brand-collab { margin: 0 16px; padding: 48px 16px; }

  .quick-links { gap: 10px; }
  .quick-link { font-size: 13px; padding: 8px 16px; }

  .section-nav { justify-content: flex-start; }
  .section-nav-link { padding: 12px 16px; font-size: 12px; }
}

/* Small phones */
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  .store-hero h1 { font-size: 32px; }
  .carousel-card { flex: 0 0 220px; }
  .product-tile-image { height: 200px; }
  .product-tile-body { padding: 18px 20px 20px; }
  .product-tile-body h3 { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
