tool_use_result.content:
/* ===== Orchard — Shared Styles ===== */
:root {
  --color-dark: #1d1d1f;
  --color-bg: #f5f5f7;
  --color-bg-alt: #fbfbfd;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #004499;
  --color-white: #ffffff;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-badge-bg: #fde8e0;
  --max-width: 1200px;
  --nav-height: 48px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', sans-serif;
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; display: block; }

/* ===== Ribbon Banner ===== */
.ribbon {
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  letter-spacing: -0.08px;
}
.ribbon a { color: #2997ff; }

/* ===== Navigation ===== */
.nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 24px;
}
.nav-logo {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-dark);
  letter-spacing: -0.5px;
}
.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  color: var(--color-text);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: -0.08px;
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--color-accent); text-decoration: none; }
.nav-links a.active { color: var(--color-accent); }

/* Mobile nav */
.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}
.nav-mobile-toggle span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-dark);
  margin: 4px 0;
  border-radius: 1px;
}

/* ===== Container ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Section ===== */
.section {
  padding: 72px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 40px;
}
.section-header h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.1;
  margin-bottom: 8px;
}
.section-header p {
  font-size: 19px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
}
.section-header-left {
  text-align: left;
}

/* ===== Hero Sections ===== */
.hero {
  text-align: center;
  padding: 60px 24px 48px;
}
.hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.08;
  margin-bottom: 12px;
}
.hero .hero-sub {
  font-size: 21px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
  margin-bottom: 28px;
  line-height: 1.4;
}
.hero-links {
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.hero-links a {
  font-size: 17px;
  color: var(--color-accent);
  font-weight: 400;
}
.hero-links a::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Product Icon Bar ===== */
.icon-bar-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}
.icon-bar {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px;
  justify-content: center;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 16px;
  cursor: pointer;
  scroll-snap-align: start;
  transition: opacity var(--transition);
  min-width: 80px;
}
.icon-bar-item:hover { opacity: 0.7; }
.icon-bar-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-bar-icon svg { width: 24px; height: 24px; }
.icon-bar-label {
  font-size: 11px;
  color: var(--color-text);
  font-weight: 500;
  letter-spacing: -0.06px;
}

/* ===== Carousel ===== */
.carousel-section {
  padding: 0 0 72px;
}
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
}
.carousel-header h2 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
}
.carousel-header p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}
.carousel-stage {
  position: relative;
}
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  font-size: 16px;
  color: var(--color-text-secondary);
}
.carousel-btn:hover {
  background: var(--color-bg);
  box-shadow: var(--shadow-md);
  color: var(--color-text);
}
.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}
.carousel-prev { left: 0; }
.carousel-next { right: 0; }

/* Carousel Card */
.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.carousel-card-image {
  width: 100%;
  height: 200px;
  background: linear-gradient(135deg, #f5f5f7 0%, #e8e8ed 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-card-image.gradient-blue { background: linear-gradient(135deg, #e3f0ff 0%, #c8ddf8 100%); }
.carousel-card-image.gradient-warm { background: linear-gradient(135deg, #fef7ed 0%, #fce4cc 100%); }
.carousel-card-image.gradient-green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.carousel-card-image.gradient-purple { background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%); }
.carousel-card-image.gradient-teal { background: linear-gradient(135deg, #e0f2f1 0%, #b2dfdb 100%); }
.carousel-card-image.gradient-rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.carousel-card-image.gradient-slate { background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%); }
.carousel-card-image svg { width: 80px; height: 80px; opacity: 0.4; }

.carousel-card-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-badge);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.carousel-card-body {
  padding: 16px 20px 20px;
}
.carousel-card-body h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.2px;
  margin-bottom: 2px;
}
.carousel-card-body .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
  line-height: 1.3;
}
.carousel-card-body .price {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
}
.carousel-card-body .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

/* Carousel promo card */
.carousel-promo {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3d 100%);
  color: white;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: var(--radius-lg);
}
.carousel-promo h3 { color: white; font-size: 19px; }
.carousel-promo .tagline { color: rgba(255,255,255,0.7); }
.carousel-promo a { color: #2997ff; font-size: 14px; margin-top: 8px; }

/* ===== Homepage Product Grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.product-tile {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  position: relative;
}
.product-tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-tile-image {
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.product-tile-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.product-tile-image.dark { background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%); }
.product-tile-image.blue { background: linear-gradient(135deg, #e8f0fe 0%, #d0e0fc 100%); }
.product-tile-image.green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.product-tile-image.rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.product-tile-image.gold { background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 100%); }

.product-tile-image svg { width: 140px; height: 140px; opacity: 0.30; }
.product-tile-image.dark svg { opacity: 0.25; color: white; }

.product-tile-body {
  padding: 24px 28px 28px;
}
.product-tile-body h3 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 4px;
}
.product-tile-body p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.3;
}
.product-tile-ctas {
  display: flex;
  gap: 20px;
}
.product-tile-ctas a {
  font-size: 15px;
  font-weight: 500;
}
.product-tile-ctas a.learn-more {
  color: var(--color-accent);
}
.product-tile-ctas a.learn-more::after {
  content: ' >';
  font-family: monospace;
}
.product-tile-ctas a.buy {
  color: var(--color-accent);
}
.product-tile-ctas a.buy::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Tabs (Entertainment) ===== */
.tabs-nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs-nav::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 24px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  font-size: 16px;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition);
  font-family: inherit;
  letter-spacing: -0.1px;
}
.tab-btn:hover { color: var(--color-text); }
.tab-btn.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeIn 0.3s ease; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Entertainment Cards */
.ent-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.ent-cards::-webkit-scrollbar { display: none; }
.ent-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.ent-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.ent-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ent-card-image.gradient-streaming { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); }
.ent-card-image.gradient-fitness { background: linear-gradient(135deg, #1b5e20 0%, #2e7d32 100%); }
.ent-card-image.gradient-gaming { background: linear-gradient(135deg, #311b92 0%, #4527a0 100%); }
.ent-card-image.gradient-music { background: linear-gradient(135deg, #b71c1c 0%, #d32f2f 100%); }
.ent-card-image svg { width: 60px; height: 60px; opacity: 0.5; color: white; }
.ent-card-body {
  padding: 16px 20px;
  background: var(--color-white);
}
.ent-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}
.ent-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}
.ent-card-body .cta-link {
  font-size: 13px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Store Hero ===== */
.store-hero {
  text-align: center;
  padding: 80px 24px 60px;
  background: var(--color-white);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.07;
  margin-bottom: 8px;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  letter-spacing: -0.15px;
  margin-bottom: 28px;
}
.cta-group {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}
.cta-btn {
  padding: 11px 22px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: inherit;
  letter-spacing: -0.1px;
}
.cta-btn.primary {
  background: var(--color-accent);
  color: white;
  border: none;
}
.cta-btn.primary:hover { background: var(--color-accent-hover); }
.cta-btn.secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}
.cta-btn.secondary:hover { background: rgba(0,102,204,0.05); }

/* ===== Help & Support Cards ===== */
.help-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.help-cards::-webkit-scrollbar { display: none; }
.help-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.help-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.help-card-icon svg { width: 24px; height: 24px; }
.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Store Difference / Savings Cards ===== */
.diff-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.diff-cards::-webkit-scrollbar { display: none; }
.diff-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.diff-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.diff-card-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
}
.diff-card-icon svg { width: 22px; height: 22px; }
.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.diff-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Brand Collab ===== */
.brand-collab {
  text-align: center;
  padding: 80px 24px;
  background: var(--color-white);
  margin: 0 24px;
  border-radius: var(--radius-xl);
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}
.brand-collab h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.brand-collab .logos {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 8px;
}
.brand-collab p {
  font-size: 19px;
  color: var(--color-text-secondary);
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 0 24px;
}
.quick-link {
  padding: 10px 20px;
  background: var(--color-white);
  border-radius: 24px;
  font-size: 14px;
  color: var(--color-text);
  font-weight: 500;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  border: 1px solid var(--color-border);
}
.quick-link:hover {
  box-shadow: var(--shadow-md);
  text-decoration: none;
  color: var(--color-accent);
}

/* ===== Category Hero ===== */
.cat-hero {
  text-align: center;
  padding: 64px 24px 32px;
  background: var(--color-white);
}
.cat-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.cat-hero p {
  font-size: 19px;
  color: var(--color-text-secondary);
}

/* ===== Sticky Section Nav ===== */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  z-index: 99;
  overflow-x: auto;
  scrollbar-width: none;
  display: flex;
  justify-content: center;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
}
.section-nav-link {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: inherit;
  letter-spacing: -0.08px;
}
.section-nav-link:hover { color: var(--color-text); }
.section-nav-link.active { color: var(--color-text); border-bottom-color: var(--color-text); }

/* ===== Guide Cards ===== */
.guide-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.guide-cards::-webkit-scrollbar { display: none; }
.guide-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.guide-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Special Stores ===== */
.special-stores {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.special-stores::-webkit-scrollbar { display: none; }
.special-store-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.special-store-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* ===== Audio Promo ===== */
.audio-promo {
  text-align: center;
  font-size: 15px;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
  padding: 12px 24px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  display: inline-block;
}

/* ===== Category Audio/Accessories ===== */
.cat-product-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.cat-product-cards::-webkit-scrollbar { display: none; }
.cat-product-card {
  flex: 0 0 220px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.cat-product-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.cat-product-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cat-product-card-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.cat-product-card-image svg { width: 70px; height: 70px; opacity: 0.35; }
.cat-product-card-badge-top {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--color-accent);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
}
.cat-product-card-body {
  padding: 14px 16px 18px;
}
.cat-product-card-body h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.cat-product-card-body .note {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}
.cat-product-card-body .price {
  font-size: 14px;
  font-weight: 500;
}

/* ===== Section backgrounds ===== */
.bg-white { background: var(--color-white); }
.bg-alt { background: var(--color-bg-alt); }

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-alt);
  padding: 40px 24px 24px;
  border-top: 1px solid var(--color-border);
}
.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 10px;
  color: var(--color-text);
  letter-spacing: -0.08px;
}
.footer-col ul {
  list-style: none;
}
.footer-col ul li {
  margin-bottom: 6px;
}
.footer-col ul li a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col ul li a:hover {
  color: var(--color-text);
  text-decoration: none;
}
.footer-bottom {
  max-width: var(--max-width);
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}
.footer-bottom p {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 8px;
}

/* ===== Responsive ===== */

/* Tablet */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile-image {
    height: 280px;
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .carousel-card { flex: 0 0 260px; }
  .hero h1, .store-hero h1, .cat-hero h1 {
    font-size: 40px;
  }
  .section { padding: 56px 0; }
}

/* Mobile */
@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(251, 251, 253, 0.98);
    backdrop-filter: blur(20px);
    flex-direction: column;
    padding: 20px 24px;
    gap: 16px;
    border-bottom: 1px solid var(--color-border);
  }
  .nav-links.open { display: flex; }
  .nav-mobile-toggle { display: block; }

  .hero h1 { font-size: 36px; }
  .hero .hero-sub { font-size: 17px; }
  .store-hero h1 { font-size: 40px; }
  .store-hero .subtitle { font-size: 18px; }
  .cat-hero h1 { font-size: 36px; }

  .section-header h2 { font-size: 32px; }
  .section-header p { font-size: 16px; }
  .section { padding: 48px 0; }

  .product-tile-image { height: 240px; }
  .product-tile-body h3 { font-size: 24px; }
  .product-tile-body p { font-size: 15px; }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  /* Footer accordion on mobile */
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px solid var(--color-border);
    margin-bottom: 0;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 400;
    transition: transform 0.3s;
  }
  .footer-col h4.open::after {
    content: '\2212';
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
  }
  .footer-col ul.open {
    max-height: 600px;
    padding: 10px 0;
  }

  .carousel-card { flex: 0 0 240px; }
  .carousel-btn { display: none; }

  .brand-collab h2 { font-size: 32px; }
  .brand-collab { margin: 0 16px; padding: 48px 16px; }

  .quick-links { gap: 10px; }
  .quick-link { font-size: 13px; padding: 8px 16px; }

  .section-nav { justify-content: flex-start; }
  .section-nav-link { padding: 12px 16px; font-size: 12px; }
}

/* Small phones */
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  .store-hero h1 { font-size: 32px; }
  .carousel-card { flex: 0 0 220px; }
  .product-tile-image { height: 200px; }
  .product-tile-body { padding: 18px 20px 20px; }
  .product-tile-body h3 { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ===== Orchard — Shared Styles ===== */
:root {
  --color-dark: #1d1d1f;
  --color-bg: #f5f5f7;
  --color-bg-alt: #fbfbfd;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #004499;
  --color-white: #ffffff;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-badge-bg: #fde8e0;
  --max-width: 1200px;
  --nav-height: 48px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', sans-serif;
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; display: block; }

/* ===== Ribbon Banner ===== */
.ribbon {
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  letter-spacing: -0.08px;
}
.ribbon a { color: #2997ff; }

/* ===== Navigation ===== */
.nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 24px;
}
.nav-logo {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-dark);
  letter-spacing: -0.5px;
}
.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  color: var(--color-text);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: -0.08px;
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--color-accent); text-decoration: none; }
.nav-links a.active { color: var(--color-accent); }

/* Mobile nav */
.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}
.nav-mobile-toggle span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-dark);
  margin: 4px 0;
  border-radius: 1px;
}

/* ===== Container ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Section ===== */
.section {
  padding: 72px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 40px;
}
.section-header h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.1;
  margin-bottom: 8px;
}
.section-header p {
  font-size: 19px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
}
.section-header-left {
  text-align: left;
}

/* ===== Hero Sections ===== */
.hero {
  text-align: center;
  padding: 60px 24px 48px;
}
.hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.08;
  margin-bottom: 12px;
}
.hero .hero-sub {
  font-size: 21px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
  margin-bottom: 28px;
  line-height: 1.4;
}
.hero-links {
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.hero-links a {
  font-size: 17px;
  color: var(--color-accent);
  font-weight: 400;
}
.hero-links a::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Product Icon Bar ===== */
.icon-bar-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}
.icon-bar {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px;
  justify-content: center;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 16px;
  cursor: pointer;
  scroll-snap-align: start;
  transition: opacity var(--transition);
  min-width: 80px;
}
.icon-bar-item:hover { opacity: 0.7; }
.icon-bar-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-bar-icon svg { width: 24px; height: 24px; }
.icon-bar-label {
  font-size: 11px;
  color: var(--color-text);
  font-weight: 500;
  letter-spacing: -0.06px;
}

/* ===== Carousel ===== */
.carousel-section {
  padding: 0 0 72px;
}
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
}
.carousel-header h2 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
}
.carousel-header p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}
.carousel-stage {
  position: relative;
}
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  font-size: 16px;
  color: var(--color-text-secondary);
}
.carousel-btn:hover {
  background: var(--color-bg);
  box-shadow: var(--shadow-md);
  color: var(--color-text);
}
.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}
.carousel-prev { left: 0; }
.carousel-next { right: 0; }

/* Carousel Card */
.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.carousel-card-image {
  width: 100%;
  height: 200px;
  background: linear-gradient(135deg, #f5f5f7 0%, #e8e8ed 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-card-image.gradient-blue { background: linear-gradient(135deg, #e3f0ff 0%, #c8ddf8 100%); }
.carousel-card-image.gradient-warm { background: linear-gradient(135deg, #fef7ed 0%, #fce4cc 100%); }
.carousel-card-image.gradient-green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.carousel-card-image.gradient-purple { background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%); }
.carousel-card-image.gradient-teal { background: linear-gradient(135deg, #e0f2f1 0%, #b2dfdb 100%); }
.carousel-card-image.gradient-rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.carousel-card-image.gradient-slate { background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%); }
.carousel-card-image svg { width: 80px; height: 80px; opacity: 0.4; }

.carousel-card-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-badge);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.carousel-card-body {
  padding: 16px 20px 20px;
}
.carousel-card-body h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.2px;
  margin-bottom: 2px;
}
.carousel-card-body .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
  line-height: 1.3;
}
.carousel-card-body .price {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
}
.carousel-card-body .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

/* Carousel promo card */
.carousel-promo {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3d 100%);
  color: white;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: var(--radius-lg);
}
.carousel-promo h3 { color: white; font-size: 19px; }
.carousel-promo .tagline { color: rgba(255,255,255,0.7); }
.carousel-promo a { color: #2997ff; font-size: 14px; margin-top: 8px; }

/* ===== Homepage Product Grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.product-tile {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  position: relative;
}
.product-tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-tile-image {
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.product-tile-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.product-tile-image.dark { background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%); }
.product-tile-image.blue { background: linear-gradient(135deg, #e8f0fe 0%, #d0e0fc 100%); }
.product-tile-image.green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.product-tile-image.rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.product-tile-image.gold { background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 100%); }

.product-tile-image svg { width: 140px; height: 140px; opacity: 0.30; }
.product-tile-image.dark svg { opacity: 0.25; color: white; }

.product-tile-body {
  padding: 24px 28px 28px;
}
.product-tile-body h3 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 4px;
}
.product-tile-body p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.3;
}
.product-tile-ctas {
  display: flex;
  gap: 20px;
}
.product-tile-ctas a {
  font-size: 15px;
  font-weight: 500;
}
.product-tile-ctas a.learn-more {
  color: var(--color-accent);
}
.product-tile-ctas a.learn-more::after {
  content: ' >';
  font-family: monospace;
}
.product-tile-ctas a.buy {
  color: var(--color-accent);
}
.product-tile-ctas a.buy::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Tabs (Entertainment) ===== */
.tabs-nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs-nav::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 24px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  font-size: 16px;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition);
  font-family: inherit;
  letter-spacing: -0.1px;
}
.tab-btn:hover { color: var(--color-text); }
.tab-btn.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeIn 0.3s ease; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Entertainment Cards */
.ent-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.ent-cards::-webkit-scrollbar { display: none; }
.ent-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.ent-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.ent-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ent-card-image.gradient-streaming { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); }
.ent-card-image.gradient-fitness { background: linear-gradient(135deg, #1b5e20 0%, #2e7d32 100%); }
.ent-card-image.gradient-gaming { background: linear-gradient(135deg, #311b92 0%, #4527a0 100%); }
.ent-card-image.gradient-music { background: linear-gradient(135deg, #b71c1c 0%, #d32f2f 100%); }
.ent-card-image svg { width: 60px; height: 60px; opacity: 0.5; color: white; }
.ent-card-body {
  padding: 16px 20px;
  background: var(--color-white);
}
.ent-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}
.ent-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}
.ent-card-body .cta-link {
  font-size: 13px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Store Hero ===== */
.store-hero {
  text-align: center;
  padding: 80px 24px 60px;
  background: var(--color-white);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.07;
  margin-bottom: 8px;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  letter-spacing: -0.15px;
  margin-bottom: 28px;
}
.cta-group {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}
.cta-btn {
  padding: 11px 22px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: inherit;
  letter-spacing: -0.1px;
}
.cta-btn.primary {
  background: var(--color-accent);
  color: white;
  border: none;
}
.cta-btn.primary:hover { background: var(--color-accent-hover); }
.cta-btn.secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}
.cta-btn.secondary:hover { background: rgba(0,102,204,0.05); }

/* ===== Help & Support Cards ===== */
.help-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.help-cards::-webkit-scrollbar { display: none; }
.help-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.help-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.help-card-icon svg { width: 24px; height: 24px; }
.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Store Difference / Savings Cards ===== */
.diff-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.diff-cards::-webkit-scrollbar { display: none; }
.diff-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.diff-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.diff-card-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
}
.diff-card-icon svg { width: 22px; height: 22px; }
.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.diff-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Brand Collab ===== */
.brand-collab {
  text-align: center;
  padding: 80px 24px;
  background: var(--color-white);
  margin: 0 24px;
  border-radius: var(--radius-xl);
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}
.brand-collab h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.brand-collab .logos {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 8px;
}
.brand-collab p {
  font-size: 19px;
  color: var(--color-text-secondary);
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 0 24px;
}
.quick-link {
  padding: 10px 20px;
  background: var(--color-white);
  border-radius: 24px;
  font-size: 14px;
  color: var(--color-text);
  font-weight: 500;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  border: 1px solid var(--color-border);
}
.quick-link:hover {
  box-shadow: var(--shadow-md);
  text-decoration: none;
  color: var(--color-accent);
}

/* ===== Category Hero ===== */
.cat-hero {
  text-align: center;
  padding: 64px 24px 32px;
  background: var(--color-white);
}
.cat-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.cat-hero p {
  font-size: 19px;
  color: var(--color-text-secondary);
}

/* ===== Sticky Section Nav ===== */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  z-index: 99;
  overflow-x: auto;
  scrollbar-width: none;
  display: flex;
  justify-content: center;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
}
.section-nav-link {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: inherit;
  letter-spacing: -0.08px;
}
.section-nav-link:hover { color: var(--color-text); }
.section-nav-link.active { color: var(--color-text); border-bottom-color: var(--color-text); }

/* ===== Guide Cards ===== */
.guide-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.guide-cards::-webkit-scrollbar { display: none; }
.guide-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.guide-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ===== Special Stores ===== */
.special-stores {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.special-stores::-webkit-scrollbar { display: none; }
.special-store-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.special-store-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* ===== Audio Promo ===== */
.audio-promo {
  text-align: center;
  font-size: 15px;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
  padding: 12px 24px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  display: inline-block;
}

/* ===== Category Audio/Accessories ===== */
.cat-product-cards {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.cat-product-cards::-webkit-scrollbar { display: none; }
.cat-product-card {
  flex: 0 0 220px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all var(--transition);
}
.cat-product-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.cat-product-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cat-product-card-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.cat-product-card-image svg { width: 70px; height: 70px; opacity: 0.35; }
.cat-product-card-badge-top {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--color-accent);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
}
.cat-product-card-body {
  padding: 14px 16px 18px;
}
.cat-product-card-body h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.cat-product-card-body .note {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}
.cat-product-card-body .price {
  font-size: 14px;
  font-weight: 500;
}

/* ===== Section backgrounds ===== */
.bg-white { background: var(--color-white); }
.bg-alt { background: var(--color-bg-alt); }

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-alt);
  padding: 40px 24px 24px;
  border-top: 1px solid var(--color-border);
}
.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 10px;
  color: var(--color-text);
  letter-spacing: -0.08px;
}
.footer-col ul {
  list-style: none;
}
.footer-col ul li {
  margin-bottom: 6px;
}
.footer-col ul li a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col ul li a:hover {
  color: var(--color-text);
  text-decoration: none;
}
.footer-bottom {
  max-width: var(--max-width);
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}
.footer-bottom p {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 8px;
}

/* ===== Responsive ===== */

/* Tablet */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile-image {
    height: 280px;
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .carousel-card { flex: 0 0 260px; }
  .hero h1, .store-hero h1, .cat-hero h1 {
    font-size: 40px;
  }
  .section { padding: 56px 0; }
}

/* Mobile */
@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(251, 251, 253, 0.98);
    backdrop-filter: blur(20px);
    flex-direction: column;
    padding: 20px 24px;
    gap: 16px;
    border-bottom: 1px solid var(--color-border);
  }
  .nav-links.open { display: flex; }
  .nav-mobile-toggle { display: block; }

  .hero h1 { font-size: 36px; }
  .hero .hero-sub { font-size: 17px; }
  .store-hero h1 { font-size: 40px; }
  .store-hero .subtitle { font-size: 18px; }
  .cat-hero h1 { font-size: 36px; }

  .section-header h2 { font-size: 32px; }
  .section-header p { font-size: 16px; }
  .section { padding: 48px 0; }

  .product-tile-image { height: 240px; }
  .product-tile-body h3 { font-size: 24px; }
  .product-tile-body p { font-size: 15px; }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  /* Footer accordion on mobile */
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px solid var(--color-border);
    margin-bottom: 0;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 400;
    transition: transform 0.3s;
  }
  .footer-col h4.open::after {
    content: '\2212';
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
  }
  .footer-col ul.open {
    max-height: 600px;
    padding: 10px 0;
  }

  .carousel-card { flex: 0 0 240px; }
  .carousel-btn { display: none; }

  .brand-collab h2 { font-size: 32px; }
  .brand-collab { margin: 0 16px; padding: 48px 16px; }

  .quick-links { gap: 10px; }
  .quick-link { font-size: 13px; padding: 8px 16px; }

  .section-nav { justify-content: flex-start; }
  .section-nav-link { padding: 12px 16px; font-size: 12px; }
}

/* Small phones */
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  .store-hero h1 { font-size: 32px; }
  .carousel-card { flex: 0 0 220px; }
  .product-tile-image { height: 200px; }
  .product-tile-body { padding: 18px 20px 20px; }
  .product-tile-body h3 { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

raw_arguments.content:
/* ===== Orchard — Shared Styles ===== */
:root {
  --color-dark: #1d1d1f;
  --color-bg: #f5f5f7;
  --color-bg-alt: #fbfbfd;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #004499;
  --color-white: #ffffff;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-badge-bg: #fde8e0;
  --max-width: 1200px;
  --nav-height: 48px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', sans-serif;
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; display: block; }

/* ===== Ribbon Banner ===== */
.ribbon {
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  letter-spacing: -0.08px;
}
.ribbon a { color: #2997ff; }

/* ===== Navigation ===== */
.nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 24px;
}
.nav-logo {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-dark);
  letter-spacing: -0.5px;
}
.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  color: var(--color-text);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: -0.08px;
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--color-accent); text-decoration: none; }
.nav-links a.active { color: var(--color-accent); }

/* Mobile nav */
.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}
.nav-mobile-toggle span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-dark);
  margin: 4px 0;
  border-radius: 1px;
}

/* ===== Container ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Section ===== */
.section {
  padding: 72px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 40px;
}
.section-header h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.1;
  margin-bottom: 8px;
}
.section-header p {
  font-size: 19px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
}
.section-header-left {
  text-align: left;
}

/* ===== Hero Sections ===== */
.hero {
  text-align: center;
  padding: 60px 24px 48px;
}
.hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.08;
  margin-bottom: 12px;
}
.hero .hero-sub {
  font-size: 21px;
  color: var(--color-text-secondary);
  letter-spacing: -0.12px;
  margin-bottom: 28px;
  line-height: 1.4;
}
.hero-links {
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.hero-links a {
  font-size: 17px;
  color: var(--color-accent);
  font-weight: 400;
}
.hero-links a::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Product Icon Bar ===== */
.icon-bar-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}
.icon-bar {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px;
  justify-content: center;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 16px;
  cursor: pointer;
  scroll-snap-align: start;
  transition: opacity var(--transition);
  min-width: 80px;
}
.icon-bar-item:hover { opacity: 0.7; }
.icon-bar-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-bar-icon svg { width: 24px; height: 24px; }
.icon-bar-label {
  font-size: 11px;
  color: var(--color-text);
  font-weight: 500;
  letter-spacing: -0.06px;
}

/* ===== Carousel ===== */
.carousel-section {
  padding: 0 0 72px;
}
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
}
.carousel-header h2 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
}
.carousel-header p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}
.carousel-stage {
  position: relative;
}
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 4px 0 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  font-size: 16px;
  color: var(--color-text-secondary);
}
.carousel-btn:hover {
  background: var(--color-bg);
  box-shadow: var(--shadow-md);
  color: var(--color-text);
}
.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}
.carousel-prev { left: 0; }
.carousel-next { right: 0; }

/* Carousel Card */
.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.carousel-card-image {
  width: 100%;
  height: 200px;
  background: linear-gradient(135deg, #f5f5f7 0%, #e8e8ed 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-card-image.gradient-blue { background: linear-gradient(135deg, #e3f0ff 0%, #c8ddf8 100%); }
.carousel-card-image.gradient-warm { background: linear-gradient(135deg, #fef7ed 0%, #fce4cc 100%); }
.carousel-card-image.gradient-green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.carousel-card-image.gradient-purple { background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%); }
.carousel-card-image.gradient-teal { background: linear-gradient(135deg, #e0f2f1 0%, #b2dfdb 100%); }
.carousel-card-image.gradient-rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.carousel-card-image.gradient-slate { background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%); }
.carousel-card-image svg { width: 80px; height: 80px; opacity: 0.4; }

.carousel-card-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-badge);
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.carousel-card-body {
  padding: 16px 20px 20px;
}
.carousel-card-body h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.2px;
  margin-bottom: 2px;
}
.carousel-card-body .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
  line-height: 1.3;
}
.carousel-card-body .price {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
}
.carousel-card-body .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

/* Carousel promo card */
.carousel-promo {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3d 100%);
  color: white;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: var(--radius-lg);
}
.carousel-promo h3 { color: white; font-size: 19px; }
.carousel-promo .tagline { color: rgba(255,255,255,0.7); }
.carousel-promo a { color: #2997ff; font-size: 14px; margin-top: 8px; }

/* ===== Homepage Product Grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.product-tile {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
  position: relative;
}
.product-tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-tile-image {
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.product-tile-image.light { background: linear-gradient(135deg, #f9f9fb 0%, #f0f0f5 100%); }
.product-tile-image.dark { background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%); }
.product-tile-image.blue { background: linear-gradient(135deg, #e8f0fe 0%, #d0e0fc 100%); }
.product-tile-image.green { background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); }
.product-tile-image.rose { background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%); }
.product-tile-image.gold { background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 100%); }

.product-tile-image svg { width: 140px; height: 140px; opacity: 0.30; }
.product-tile-image.dark svg { opacity: 0.25; color: white; }

.product-tile-body {
  padding: 24px 28px 28px;
}
.product-tile-body h3 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 4px;
}
.product-tile-body p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.3;
}
.product-tile-ctas {
  display: flex;
  gap: 20px;
}
.product-tile-ctas a {
  font-size: 15px;
  font-weight: 500;
}
.product-tile-ctas a.learn-more {
  color: var(--color-accent);
}
.product-tile-ctas a.learn-more::after {
  content: ' >';
  font-family: monospace;
}
.product-tile-ctas a.buy {
  color: var(--color-accent);
}
.product-tile-ctas a.buy::after {
  content: ' >';
  font-family: monospace;
}

/* ===== Tabs (Entertainment) ===== */
.tabs-nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs-nav::-webkit-scrollbar { display: none; }
.tab-btn {
